def create_issue(workspace_id, team_id, project_id=None, title=None, description=None, priority=None, status=None, labels=None, due_date=None, **_extra):
    import json, os, datetime, re, time, base64, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0148000" if __import__("os").path.isdir("./environment_mix/0148000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)
    now_s = now.isoformat()

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            ss = s.strip()
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(ss)
        except Exception:
            return None

    def _new_id(prefix, existing_ids):
        # Deterministic-ish unique id, offline safe
        seed = f"{prefix}:{now.timestamp()}:{os.getpid()}:{len(existing_ids)}".encode("utf-8")
        tok = base64.b32encode(hashlib.sha1(seed).digest()).decode("utf-8").rstrip("=")
        tok = re.sub(r"[^0-9A-Z]", "", tok)[:16]
        cand = f"{prefix}_{tok}"
        i = 0
        while cand in existing_ids:
            i += 1
            seed2 = f"{seed.decode('utf-8')}:{i}".encode("utf-8")
            tok = base64.b32encode(hashlib.sha1(seed2).digest()).decode("utf-8").rstrip("=")
            tok = re.sub(r"[^0-9A-Z]", "", tok)[:16]
            cand = f"{prefix}_{tok}"
        return cand

    def _log_request(status, payload, response_summary=None, error_message=None, workspace_for_log=None):
        api_requests = _load("api_requests.json")
        existing_ids = {r.get("id") for r in api_requests if isinstance(r, dict)}
        rid = _new_id("lin_req", existing_ids)
        row = {
            "id": rid,
            "workspace_id": workspace_for_log,
            "tool_name": "create_issue",
            "status": "received",
            "request_payload": payload if isinstance(payload, dict) else {},
            "response_summary": None,
            "error_message": None,
            "duration_ms": None,
            "created_at": now_s,
            "updated_at": now_s,
        }
        api_requests.append(row)
        _save("api_requests.json", api_requests)

        end = datetime.datetime.now(datetime.timezone.utc)
        dur = int(max(0, (time.time() - t0) * 1000))
        row["updated_at"] = end.isoformat()
        row["duration_ms"] = dur
        row["status"] = status
        row["response_summary"] = response_summary
        row["error_message"] = error_message
        _save("api_requests.json", api_requests)

    payload = {
        "workspace_id": workspace_id,
        "team_id": team_id,
        "project_id": project_id,
        "title": title,
        "description": description,
        "priority": priority,
        "status": status,
        "labels": labels,
        "due_date": due_date,
    }

    # Validate inputs
    if not isinstance(workspace_id, str) or not re.match(r"^lin_ws_[0-9A-Z]+$", workspace_id):
        _log_request("failed", payload, error_message="Invalid workspace_id format", workspace_for_log=None)
        return _err("VALIDATION_ERROR", "Invalid workspace_id format")
    if not isinstance(team_id, str) or not re.match(r"^lin_team_[0-9A-Z]+$", team_id):
        _log_request("failed", payload, error_message="Invalid team_id format", workspace_for_log=workspace_id)
        return _err("VALIDATION_ERROR", "Invalid team_id format")
    if project_id is not None:
        if not isinstance(project_id, str) or not re.match(r"^lin_prj_[0-9A-Z]+$", project_id):
            _log_request("failed", payload, error_message="Invalid project_id format", workspace_for_log=workspace_id)
            return _err("VALIDATION_ERROR", "Invalid project_id format")
    if not isinstance(title, str) or title.strip() == "":
        _log_request("failed", payload, error_message="title must be a non-empty string", workspace_for_log=workspace_id)
        return _err("VALIDATION_ERROR", "title must be a non-empty string")
    if description is not None and not isinstance(description, str):
        _log_request("failed", payload, error_message="description must be string or null", workspace_for_log=workspace_id)
        return _err("VALIDATION_ERROR", "description must be string or null")
    if priority is not None and (not isinstance(priority, int) or priority not in [0, 1, 2, 3, 4]):
        _log_request("failed", payload, error_message="Invalid priority", workspace_for_log=workspace_id)
        return _err("VALIDATION_ERROR", "Invalid priority")
    if status is not None and (not isinstance(status, str) or status not in ["triage", "backlog", "started", "completed", "canceled"]):
        _log_request("failed", payload, error_message="Invalid status", workspace_for_log=workspace_id)
        return _err("VALIDATION_ERROR", "Invalid status")
    if labels is not None:
        if not isinstance(labels, list) or any(not isinstance(x, str) for x in labels):
            _log_request("failed", payload, error_message="labels must be an array of strings", workspace_for_log=workspace_id)
            return _err("VALIDATION_ERROR", "labels must be an array of strings")
        if len(labels) > 50:
            _log_request("failed", payload, error_message="Too many labels (max 50)", workspace_for_log=workspace_id)
            return _err("VALIDATION_ERROR", "Too many labels (max 50)")
    if due_date is not None:
        dt = _parse_dt(due_date)
        if dt is None:
            _log_request("failed", payload, error_message="due_date must be ISO 8601 date-time or null", workspace_for_log=workspace_id)
            return _err("VALIDATION_ERROR", "due_date must be ISO 8601 date-time or null")

    # Load refs
    workspaces = _load("workspaces.json")
    ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == workspace_id), None)
    if not ws:
        _log_request("failed", payload, error_message="Workspace not found", workspace_for_log=None)
        return _err("NOT_FOUND", "Workspace not found")
    if ws.get("status") != "active":
        _log_request("failed", payload, error_message="Workspace not active", workspace_for_log=workspace_id)
        return _err("UNAUTHORIZED", "Workspace not active")

    teams = _load("teams.json")
    team = next((t for t in teams if isinstance(t, dict) and t.get("id") == team_id), None)
    if not team:
        _log_request("failed", payload, error_message="Team not found", workspace_for_log=workspace_id)
        return _err("NOT_FOUND", "Team not found")
    if team.get("workspace_id") != workspace_id:
        _log_request("failed", payload, error_message="Cross-workspace access forbidden", workspace_for_log=workspace_id)
        return _err("UNAUTHORIZED", "Cross-workspace access forbidden")
    if team.get("status") != "active":
        _log_request("failed", payload, error_message="Team is not active", workspace_for_log=workspace_id)
        return _err("CONFLICT", "Team is not active")

    prj = None
    if project_id is not None:
        projects = _load("projects.json")
        prj = next((p for p in projects if isinstance(p, dict) and p.get("id") == project_id), None)
        if not prj:
            _log_request("failed", payload, error_message="Project not found", workspace_for_log=workspace_id)
            return _err("NOT_FOUND", "Project not found")
        if prj.get("workspace_id") != workspace_id:
            _log_request("failed", payload, error_message="Cross-workspace access forbidden", workspace_for_log=workspace_id)
            return _err("UNAUTHORIZED", "Cross-workspace access forbidden")

    issues = _load("issues.json")

    # Transaction-like: compute next number for team based on current file content.
    max_num = 0
    for iss in issues:
        if isinstance(iss, dict) and iss.get("team_id") == team_id:
            n = iss.get("number")
            if isinstance(n, int) and n > max_num:
                max_num = n
    next_num = max_num + 1
    if next_num < 1:
        next_num = 1

    identifier = f"{team.get('key')}-{next_num}"
    # Uniqueness constraints
    if any(isinstance(iss, dict) and iss.get("team_id") == team_id and iss.get("number") == next_num for iss in issues):
        _log_request("failed", payload, error_message="Issue number conflict", workspace_for_log=workspace_id)
        return _err("CONFLICT", "Issue number conflict")
    if any(isinstance(iss, dict) and iss.get("workspace_id") == workspace_id and iss.get("identifier") == identifier for iss in issues):
        _log_request("failed", payload, error_message="Issue identifier conflict", workspace_for_log=workspace_id)
        return _err("CONFLICT", "Issue identifier conflict")

    existing_ids = {r.get("id") for r in issues if isinstance(r, dict)}
    issue_id = _new_id("lin_iss", existing_ids)

    issue_status = status if status is not None else "triage"
    issue_priority = priority if priority is not None else 3
    issue_labels = labels if labels is not None else []

    completed_at = None
    if issue_status == "completed":
        completed_at = now_s

    new_issue = {
        "id": issue_id,
        "workspace_id": workspace_id,
        "team_id": team_id,
        "project_id": project_id,
        "number": next_num,
        "identifier": identifier,
        "title": title,
        "description": description,
        "priority": issue_priority,
        "status": issue_status,
        "labels": issue_labels,
        "due_date": due_date,
        "created_at": now_s,
        "updated_at": now_s,
        "completed_at": completed_at,
    }

    issues.append(new_issue)
    _save("issues.json", issues)

    _log_request("succeeded", payload, response_summary={"created_issue_id": issue_id, "identifier": identifier}, workspace_for_log=workspace_id)
    return {
        "issue": new_issue
    }

def list_issues(workspace_id, team_id=None, project_id=None, status=None, priority=None, label=None, created_after=None, created_before=None, updated_after=None, updated_before=None, sort=None, order=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, re, time, base64, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0148000" if __import__("os").path.isdir("./environment_mix/0148000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)
    now_s = now.isoformat()

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            ss = s.strip()
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(ss)
        except Exception:
            return None

    def _new_id(prefix, existing_ids):
        seed = f"{prefix}:{now.timestamp()}:{os.getpid()}:{len(existing_ids)}".encode("utf-8")
        tok = base64.b32encode(hashlib.sha1(seed).digest()).decode("utf-8").rstrip("=")
        tok = re.sub(r"[^0-9A-Z]", "", tok)[:16]
        cand = f"{prefix}_{tok}"
        i = 0
        while cand in existing_ids:
            i += 1
            seed2 = f"{seed.decode('utf-8')}:{i}".encode("utf-8")
            tok = base64.b32encode(hashlib.sha1(seed2).digest()).decode("utf-8").rstrip("=")
            tok = re.sub(r"[^0-9A-Z]", "", tok)[:16]
            cand = f"{prefix}_{tok}"
        return cand

    def _log_request(status_s, payload, response_summary=None, error_message=None, workspace_for_log=None):
        api_requests = _load("api_requests.json")
        existing_ids = {r.get("id") for r in api_requests if isinstance(r, dict)}
        rid = _new_id("lin_req", existing_ids)
        row = {
            "id": rid,
            "workspace_id": workspace_for_log,
            "tool_name": "list_issues",
            "status": "received",
            "request_payload": payload if isinstance(payload, dict) else {},
            "response_summary": None,
            "error_message": None,
            "duration_ms": None,
            "created_at": now_s,
            "updated_at": now_s,
        }
        api_requests.append(row)
        _save("api_requests.json", api_requests)

        end = datetime.datetime.now(datetime.timezone.utc)
        dur = int(max(0, (time.time() - t0) * 1000))
        row["updated_at"] = end.isoformat()
        row["duration_ms"] = dur
        row["status"] = status_s
        row["response_summary"] = response_summary
        row["error_message"] = error_message
        _save("api_requests.json", api_requests)

    payload = {
        "workspace_id": workspace_id,
        "team_id": team_id,
        "project_id": project_id,
        "status": status,
        "priority": priority,
        "label": label,
        "created_after": created_after,
        "created_before": created_before,
        "updated_after": updated_after,
        "updated_before": updated_before,
        "sort": sort,
        "order": order,
        "limit": limit,
        "cursor": cursor,
    }

    if not isinstance(workspace_id, str) or not re.match(r"^lin_ws_[0-9A-Z]+$", workspace_id):
        _log_request("failed", payload, error_message="Invalid workspace_id format", workspace_for_log=None)
        return _err("VALIDATION_ERROR", "Invalid workspace_id format")
    if team_id is not None and (not isinstance(team_id, str) or not re.match(r"^lin_team_[0-9A-Z]+$", team_id)):
        _log_request("failed", payload, error_message="Invalid team_id format", workspace_for_log=workspace_id)
        return _err("VALIDATION_ERROR", "Invalid team_id format")
    if project_id is not None and (not isinstance(project_id, str) or not re.match(r"^lin_prj_[0-9A-Z]+$", project_id)):
        _log_request("failed", payload, error_message="Invalid project_id format", workspace_for_log=workspace_id)
        return _err("VALIDATION_ERROR", "Invalid project_id format")
    if status is not None and (not isinstance(status, str) or status not in ["triage", "backlog", "started", "completed", "canceled"]):
        _log_request("failed", payload, error_message="Invalid status", workspace_for_log=workspace_id)
        return _err("VALIDATION_ERROR", "Invalid status")
    if priority is not None and (not isinstance(priority, int) or priority not in [0, 1, 2, 3, 4]):
        _log_request("failed", payload, error_message="Invalid priority", workspace_for_log=workspace_id)
        return _err("VALIDATION_ERROR", "Invalid priority")
    if label is not None and not isinstance(label, str):
        _log_request("failed", payload, error_message="label must be string", workspace_for_log=workspace_id)
        return _err("VALIDATION_ERROR", "label must be string")

    ca = _parse_dt(created_after) if created_after is not None else None
    cb = _parse_dt(created_before) if created_before is not None else None
    ua = _parse_dt(updated_after) if updated_after is not None else None
    ub = _parse_dt(updated_before) if updated_before is not None else None
    if created_after is not None and ca is None:
        _log_request("failed", payload, error_message="created_after must be ISO 8601 date-time", workspace_for_log=workspace_id)
        return _err("VALIDATION_ERROR", "created_after must be ISO 8601 date-time")
    if created_before is not None and cb is None:
        _log_request("failed", payload, error_message="created_before must be ISO 8601 date-time", workspace_for_log=workspace_id)
        return _err("VALIDATION_ERROR", "created_before must be ISO 8601 date-time")
    if updated_after is not None and ua is None:
        _log_request("failed", payload, error_message="updated_after must be ISO 8601 date-time", workspace_for_log=workspace_id)
        return _err("VALIDATION_ERROR", "updated_after must be ISO 8601 date-time")
    if updated_before is not None and ub is None:
        _log_request("failed", payload, error_message="updated_before must be ISO 8601 date-time", workspace_for_log=workspace_id)
        return _err("VALIDATION_ERROR", "updated_before must be ISO 8601 date-time")

    if sort is not None and sort not in ["created_at", "updated_at", "priority", "due_date", "number"]:
        _log_request("failed", payload, error_message="Invalid sort", workspace_for_log=workspace_id)
        return _err("VALIDATION_ERROR", "Invalid sort")
    if order is not None and order not in ["asc", "desc"]:
        _log_request("failed", payload, error_message="Invalid order", workspace_for_log=workspace_id)
        return _err("VALIDATION_ERROR", "Invalid order")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 100:
        _log_request("failed", payload, error_message="limit out of range", workspace_for_log=workspace_id)
        return _err("VALIDATION_ERROR", "limit out of range")

    # Workspace existence & active check
    workspaces = _load("workspaces.json")
    ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == workspace_id), None)
    if not ws:
        _log_request("failed", payload, error_message="Workspace not found", workspace_for_log=None)
        return _err("NOT_FOUND", "Workspace not found")
    if ws.get("status") != "active":
        _log_request("failed", payload, error_message="Workspace not active", workspace_for_log=workspace_id)
        return _err("UNAUTHORIZED", "Workspace not active")

    teams = _load("teams.json")
    team_by_id = {t.get("id"): t for t in teams if isinstance(t, dict) and t.get("workspace_id") == workspace_id}

    if team_id is not None:
        t = team_by_id.get(team_id)
        if not t:
            _log_request("failed", payload, error_message="Team not found", workspace_for_log=workspace_id)
            return _err("NOT_FOUND", "Team not found")

    if project_id is not None:
        projects = _load("projects.json")
        prj = next((p for p in projects if isinstance(p, dict) and p.get("id") == project_id), None)
        if not prj:
            _log_request("failed", payload, error_message="Project not found", workspace_for_log=workspace_id)
            return _err("NOT_FOUND", "Project not found")
        if prj.get("workspace_id") != workspace_id:
            _log_request("failed", payload, error_message="Cross-workspace access forbidden", workspace_for_log=workspace_id)
            return _err("UNAUTHORIZED", "Cross-workspace access forbidden")

    issues = _load("issues.json")
    scoped = [i for i in issues if isinstance(i, dict) and i.get("workspace_id") == workspace_id]

    # Filters
    if team_id is not None:
        scoped = [i for i in scoped if i.get("team_id") == team_id]
    if project_id is not None:
        scoped = [i for i in scoped if i.get("project_id") == project_id]
    if status is not None:
        scoped = [i for i in scoped if i.get("status") == status]
    if priority is not None:
        scoped = [i for i in scoped if i.get("priority") == priority]
    if label is not None:
        scoped = [i for i in scoped if isinstance(i.get("labels"), list) and label in i.get("labels")]

    def _dt_field(row, field):
        v = row.get(field)
        if not isinstance(v, str):
            return None
        return _parse_dt(v)

    if ca is not None:
        scoped = [i for i in scoped if (_dt_field(i, "created_at") is not None and _dt_field(i, "created_at") > ca)]
    if cb is not None:
        scoped = [i for i in scoped if (_dt_field(i, "created_at") is not None and _dt_field(i, "created_at") < cb)]
    if ua is not None:
        scoped = [i for i in scoped if (_dt_field(i, "updated_at") is not None and _dt_field(i, "updated_at") > ua)]
    if ub is not None:
        scoped = [i for i in scoped if (_dt_field(i, "updated_at") is not None and _dt_field(i, "updated_at") < ub)]

    # Sorting
    sfield = sort or "updated_at"
    sorder = order or "desc"

    def _sort_key(row):
        if sfield in ("created_at", "updated_at", "due_date"):
            dt = _dt_field(row, sfield)
            # None sorts last for desc, first for asc; normalize via tuple
            missing = 1 if dt is None else 0
            # use timestamp; if None, 0
            ts = dt.timestamp() if dt is not None else 0.0
            return (missing, ts, row.get("id") or "")
        elif sfield == "priority":
            v = row.get("priority")
            v = v if isinstance(v, int) else 999
            return (v, row.get("updated_at") or "", row.get("id") or "")
        elif sfield == "number":
            v = row.get("number")
            v = v if isinstance(v, int) else 0
            return (v, row.get("updated_at") or "", row.get("id") or "")
        return (row.get("updated_at") or "", row.get("id") or "")

    reverse = (sorder == "desc")
    scoped.sort(key=_sort_key, reverse=reverse)

    # Cursor pagination: cursor is base64url of integer offset
    offset = 0
    if cursor is not None:
        if not isinstance(cursor, str) or cursor.strip() == "":
            _log_request("failed", payload, error_message="Invalid cursor", workspace_for_log=workspace_id)
            return _err("VALIDATION_ERROR", "Invalid cursor")
        try:
            pad = "=" * ((4 - len(cursor) % 4) % 4)
            raw = base64.urlsafe_b64decode((cursor + pad).encode("utf-8")).decode("utf-8")
            offset = int(raw)
            if offset < 0:
                raise ValueError()
        except Exception:
            _log_request("failed", payload, error_message="Invalid cursor", workspace_for_log=workspace_id)
            return _err("VALIDATION_ERROR", "Invalid cursor")

    total = len(scoped)
    page = scoped[offset:offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = None
    if has_more:
        next_cursor = base64.urlsafe_b64encode(str(next_offset).encode("utf-8")).decode("utf-8").rstrip("=")

    _log_request("succeeded", payload, response_summary={"returned": len(page), "total": total, "has_more": has_more}, workspace_for_log=workspace_id)
    return {
        "issues": page,
        "meta": {
            "total": total,
            "limit": limit,
            "has_more": has_more,
            "next_cursor": next_cursor
        }
    }

def update_issue(issue_id, title=None, description=None, priority=None, status=None, labels=None, due_date=None, project_id=None, team_id=None, **_extra):
    import json, os, datetime, re, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0148000" if __import__("os").path.isdir("./environment_mix/0148000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now_s = now_dt.isoformat() + "Z"

    # --- request logging helpers ---
    def _new_req_id(existing_ids):
        base = datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f").upper()
        cand = "lin_req_" + base
        i = 0
        while cand in existing_ids:
            i += 1
            cand = "lin_req_" + base + str(i)
        return cand

    def _append_req_received(payload):
        api_requests = _load("api_requests.json")
        if not isinstance(api_requests, list):
            api_requests = []
        existing = {r.get("id") for r in api_requests if isinstance(r, dict)}
        rid = _new_req_id(existing)
        row = {
            "id": rid,
            "workspace_id": None,
            "tool_name": "update_issue",
            "status": "received",
            "request_payload": payload if isinstance(payload, dict) else {},
            "response_summary": None,
            "error_message": None,
            "duration_ms": None,
            "created_at": now_s,
            "updated_at": now_s,
        }
        api_requests.append(row)
        _save("api_requests.json", api_requests)
        return rid

    def _finalize_req(rid, status_s, workspace_id, summary=None, error_message=None):
        api_requests = _load("api_requests.json")
        if not isinstance(api_requests, list):
            api_requests = []
        for r in reversed(api_requests):
            if isinstance(r, dict) and r.get("id") == rid:
                r["workspace_id"] = workspace_id
                r["status"] = status_s
                r["response_summary"] = summary
                r["error_message"] = error_message
                r["duration_ms"] = max(0, int((time.time() - t0) * 1000))
                r["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
                break
        _save("api_requests.json", api_requests)

    def _pick_accessible_workspace():
        # Ambient auth: choose a workspace that can serve the operation.
        # For update_issue: need an active workspace with at least one issue (so the caller can update something).
        wss = _load("workspaces.json")
        issues = _load("issues.json")
        if not isinstance(wss, list):
            wss = []
        if not isinstance(issues, list):
            issues = []
        ws_by_id = {w.get("id"): w for w in wss if isinstance(w, dict) and isinstance(w.get("id"), str)}
        # Prefer workspace owning the issue_id if present (even if suspended; rule doesn't forbid reads/writes by status explicitly,
        # but keep it realistic: avoid deleted).
        for iss in issues:
            if isinstance(iss, dict) and iss.get("id") == issue_id:
                wid = iss.get("workspace_id")
                w = ws_by_id.get(wid)
                if isinstance(w, dict) and w.get("status") != "deleted":
                    return wid
        # Otherwise pick any non-deleted workspace with issues
        ws_with_issues = set(
            iss.get("workspace_id")
            for iss in issues
            if isinstance(iss, dict) and isinstance(iss.get("workspace_id"), str)
        )
        for wid in ws_with_issues:
            w = ws_by_id.get(wid)
            if isinstance(w, dict) and w.get("status") != "deleted":
                return wid
        # Fallback: any non-deleted workspace
        for w in wss:
            if isinstance(w, dict) and w.get("status") != "deleted" and isinstance(w.get("id"), str):
                return w["id"]
        return None

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return "type"
        # Accept Z; basic ISO8601 validation/parse
        try:
            ss = s.strip()
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            datetime.datetime.fromisoformat(ss)
            return None
        except Exception:
            return "format"

    req_payload = {
        "issue_id": issue_id,
        "title": title,
        "description": description,
        "priority": priority,
        "status": status,
        "labels": labels,
        "due_date": due_date,
        "project_id": project_id,
        "team_id": team_id,
    }
    rid = _append_req_received(req_payload)

    workspace_id = None
    try:
        # --- validate inputs first ---
        if not isinstance(issue_id, str) or not re.match(r"^lin_iss_[0-9A-Z]+$", issue_id):
            workspace_id = _pick_accessible_workspace()
            _finalize_req(rid, "failed", workspace_id, error_message="validation error: issue_id must match ^lin_iss_[0-9A-Z]+$")
            return _err("VALIDATION_ERROR", "validation error: issue_id must match ^lin_iss_[0-9A-Z]+$")

        if title is not None and not isinstance(title, str):
            workspace_id = _pick_accessible_workspace()
            _finalize_req(rid, "failed", workspace_id, error_message="validation error: title must be a string")
            return _err("VALIDATION_ERROR", "validation error: title must be a string")
        if isinstance(title, str) and title == "":
            workspace_id = _pick_accessible_workspace()
            _finalize_req(rid, "failed", workspace_id, error_message="validation error: title must not be empty")
            return _err("VALIDATION_ERROR", "validation error: title must not be empty")

        if description is not None and not isinstance(description, str):
            # description may be None (clear) or string
            workspace_id = _pick_accessible_workspace()
            _finalize_req(rid, "failed", workspace_id, error_message="validation error: description must be a string or null")
            return _err("VALIDATION_ERROR", "validation error: description must be a string or null")

        if priority is not None:
            if not isinstance(priority, int) or priority not in (0, 1, 2, 3, 4):
                workspace_id = _pick_accessible_workspace()
                _finalize_req(rid, "failed", workspace_id, error_message="validation error: priority must be one of 0,1,2,3,4")
                return _err("VALIDATION_ERROR", "validation error: priority must be one of 0,1,2,3,4")

        if status is not None:
            if not isinstance(status, str) or status not in ("triage", "backlog", "started", "completed", "canceled"):
                workspace_id = _pick_accessible_workspace()
                _finalize_req(rid, "failed", workspace_id, error_message="validation error: status must be one of triage, backlog, started, completed, canceled")
                return _err("VALIDATION_ERROR", "validation error: status must be one of triage, backlog, started, completed, canceled")

        if labels is not None:
            if not isinstance(labels, list) or any(not isinstance(x, str) for x in labels):
                workspace_id = _pick_accessible_workspace()
                _finalize_req(rid, "failed", workspace_id, error_message="validation error: labels must be an array of strings")
                return _err("VALIDATION_ERROR", "validation error: labels must be an array of strings")
            if len(labels) > 50:
                workspace_id = _pick_accessible_workspace()
                _finalize_req(rid, "failed", workspace_id, error_message="validation error: array_length(labels) must be <= 50")
                return _err("VALIDATION_ERROR", "validation error: array_length(labels) must be <= 50")

        if due_date is not None:
            if due_date is not None:
                dt_err = _parse_dt(due_date)
                if dt_err == "type":
                    workspace_id = _pick_accessible_workspace()
                    _finalize_req(rid, "failed", workspace_id, error_message="validation error: due_date must be an ISO 8601 date-time string or null")
                    return _err("VALIDATION_ERROR", "validation error: due_date must be an ISO 8601 date-time string or null")
                if dt_err == "format":
                    workspace_id = _pick_accessible_workspace()
                    _finalize_req(rid, "failed", workspace_id, error_message="validation error: due_date must be ISO 8601 date-time")
                    return _err("VALIDATION_ERROR", "validation error: due_date must be ISO 8601 date-time")

        if project_id is not None:
            if project_id is not None and (not isinstance(project_id, str) or not re.match(r"^lin_prj_[0-9A-Z]+$", project_id)):
                workspace_id = _pick_accessible_workspace()
                _finalize_req(rid, "failed", workspace_id, error_message="validation error: project_id must match ^lin_prj_[0-9A-Z]+$ or be null")
                return _err("VALIDATION_ERROR", "validation error: project_id must match ^lin_prj_[0-9A-Z]+$ or be null")

        if team_id is not None:
            if not isinstance(team_id, str) or not re.match(r"^lin_team_[0-9A-Z]+$", team_id):
                workspace_id = _pick_accessible_workspace()
                _finalize_req(rid, "failed", workspace_id, error_message="validation error: team_id must match ^lin_team_[0-9A-Z]+$")
                return _err("VALIDATION_ERROR", "validation error: team_id must match ^lin_team_[0-9A-Z]+$")

        # --- load rows ---
        issues = _load("issues.json")
        teams = _load("teams.json")
        projects = _load("projects.json")
        workspaces = _load("workspaces.json")
        if not isinstance(issues, list):
            issues = []
        if not isinstance(teams, list):
            teams = []
        if not isinstance(projects, list):
            projects = []
        if not isinstance(workspaces, list):
            workspaces = []

        teams_by_id = {t.get("id"): t for t in teams if isinstance(t, dict) and isinstance(t.get("id"), str)}
        projects_by_id = {p.get("id"): p for p in projects if isinstance(p, dict) and isinstance(p.get("id"), str)}
        ws_by_id = {w.get("id"): w for w in workspaces if isinstance(w, dict) and isinstance(w.get("id"), str)}

        # Locate issue anywhere first, to infer workspace context correctly (ambient auth must pick a combination that exists)
        issue = None
        for it in issues:
            if isinstance(it, dict) and it.get("id") == issue_id:
                issue = it
                break

        if not issue:
            workspace_id = _pick_accessible_workspace()
            _finalize_req(rid, "failed", workspace_id, error_message="not found: issue_id does not exist in workspace")
            return _err("NOT_FOUND", "not found: issue_id does not exist in workspace")

        workspace_id = issue.get("workspace_id")
        if not isinstance(workspace_id, str) or workspace_id not in ws_by_id or ws_by_id[workspace_id].get("status") == "deleted":
            # treat as unauthorized context rather than leaking cross-workspace
            _finalize_req(rid, "failed", None, error_message="unauthorized: no accessible workspace context")
            return _err("UNAUTHORIZED", "unauthorized: no accessible workspace context")

        # Enforce scoping + FK integrity on existing row
        cur_team = teams_by_id.get(issue.get("team_id"))
        if not isinstance(cur_team, dict) or cur_team.get("workspace_id") != workspace_id:
            _finalize_req(rid, "failed", workspace_id, error_message="forbidden: issue.team_id does not belong to workspace")
            return _err("UNAUTHORIZED", "forbidden: issue.team_id does not belong to workspace")

        cur_project_id = issue.get("project_id")
        if cur_project_id is not None:
            cur_project = projects_by_id.get(cur_project_id)
            if not isinstance(cur_project, dict) or cur_project.get("workspace_id") != workspace_id:
                _finalize_req(rid, "failed", workspace_id, error_message="forbidden: issue.project_id does not belong to workspace")
                return _err("UNAUTHORIZED", "forbidden: issue.project_id does not belong to workspace")

        # --- enforce immutables (business rule says reject updates to these fields)
        # Note: tool schema includes team_id as a parameter, but business rules explicitly say team_id is immutable.
        # Therefore, if team_id is provided and differs, reject; if it's the same as current, allow (idempotent).
        if team_id is not None and team_id != issue.get("team_id"):
            _finalize_req(rid, "failed", workspace_id, error_message="validation error: team_id is immutable (business rule)")
            return _err("VALIDATION_ERROR", "validation error: team_id is immutable (business rule)")

        # Validate referenced project if provided
        if project_id is not None and project_id is not None:
            pr = projects_by_id.get(project_id)
            if not isinstance(pr, dict):
                _finalize_req(rid, "failed", workspace_id, error_message="not found: project_id does not exist")
                return _err("NOT_FOUND", "not found: project_id does not exist")
            if pr.get("workspace_id") != workspace_id:
                _finalize_req(rid, "failed", workspace_id, error_message="forbidden: project_id does not belong to workspace")
                return _err("UNAUTHORIZED", "forbidden: project_id does not belong to workspace")

        # lifecycle transitions for issue status
        transitions = {
            "triage": {"backlog", "started", "canceled"},
            "backlog": {"started", "canceled"},
            "started": {"completed", "backlog", "canceled"},
            "completed": {"started"},
            "canceled": {"backlog"},
        }

        old_status = issue.get("status")
        if status is not None:
            if not isinstance(old_status, str) or old_status not in transitions:
                _finalize_req(rid, "failed", workspace_id, error_message="validation error: issue has invalid current status")
                return _err("VALIDATION_ERROR", "validation error: issue has invalid current status")
            if status != old_status:
                if status not in transitions.get(old_status, set()):
                    _finalize_req(
                        rid,
                        "failed",
                        workspace_id,
                        error_message=f"invalid transition: cannot change status from {old_status} to {status}",
                    )
                    return _err("INVALID_TRANSITION", f"invalid transition: cannot change status from {old_status} to {status}")

        # Apply updates (only mutables)
        changed = False
        if title is not None and title != issue.get("title"):
            issue["title"] = title
            changed = True

        if description is not None or description is None:
            # only update if parameter was provided (including explicit None) - we cannot distinguish here,
            # but function signature default None means caller might omit; so update only if _extra indicates? Not available.
            # We approximate: update if description is not None OR if "description" was explicitly passed as None via tool.
            # Many MCP callers pass explicit null; we'll accept that by checking _extra for key presence.
            pass
        if "description" in _extra or description is not None:
            if description != issue.get("description"):
                issue["description"] = description
                changed = True

        if priority is not None and priority != issue.get("priority"):
            issue["priority"] = priority
            changed = True

        if labels is not None and labels != issue.get("labels"):
            issue["labels"] = labels
            changed = True

        if due_date is not None or "due_date" in _extra:
            if due_date != issue.get("due_date"):
                issue["due_date"] = due_date
                changed = True

        if project_id is not None or "project_id" in _extra:
            if project_id != issue.get("project_id"):
                issue["project_id"] = project_id
                changed = True

        if status is not None and status != old_status:
            issue["status"] = status
            changed = True
            # completed_at rule
            if status == "completed":
                issue["completed_at"] = now_s
            elif old_status == "completed" and status != "completed":
                issue["completed_at"] = None

        if not changed:
            # Idempotent update: still a real success, return current issue
            _finalize_req(rid, "succeeded", workspace_id, summary={"issue_id": issue_id, "updated": False})
            return {"issue": issue}

        issue["updated_at"] = now_s
        _save("issues.json", issues)

        _finalize_req(rid, "succeeded", workspace_id, summary={"issue_id": issue_id, "updated": True})
        return {"issue": issue}
    except Exception as e:
        # unexpected condition
        _finalize_req(rid, "failed", workspace_id, error_message=str(e))
        return _err("VALIDATION_ERROR", "internal error", detail=str(e))

def list_teams(workspace_id, status=None, sort=None, order=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, re, time, base64, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0148000" if __import__("os").path.isdir("./environment_mix/0148000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)
    now_s = now.isoformat()

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            ss = s.strip()
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(ss)
        except Exception:
            return None

    def _new_id(prefix, existing_ids):
        seed = f"{prefix}:{now.timestamp()}:{os.getpid()}:{len(existing_ids)}".encode("utf-8")
        tok = base64.b32encode(hashlib.sha1(seed).digest()).decode("utf-8").rstrip("=")
        tok = re.sub(r"[^0-9A-Z]", "", tok)[:16]
        cand = f"{prefix}_{tok}"
        i = 0
        while cand in existing_ids:
            i += 1
            seed2 = f"{seed.decode('utf-8')}:{i}".encode("utf-8")
            tok = base64.b32encode(hashlib.sha1(seed2).digest()).decode("utf-8").rstrip("=")
            tok = re.sub(r"[^0-9A-Z]", "", tok)[:16]
            cand = f"{prefix}_{tok}"
        return cand

    def _log_request(status_s, payload, response_summary=None, error_message=None, workspace_for_log=None):
        api_requests = _load("api_requests.json")
        existing_ids = {r.get("id") for r in api_requests if isinstance(r, dict)}
        rid = _new_id("lin_req", existing_ids)
        row = {
            "id": rid,
            "workspace_id": workspace_for_log,
            "tool_name": "list_teams",
            "status": "received",
            "request_payload": payload if isinstance(payload, dict) else {},
            "response_summary": None,
            "error_message": None,
            "duration_ms": None,
            "created_at": now_s,
            "updated_at": now_s,
        }
        api_requests.append(row)
        _save("api_requests.json", api_requests)

        end = datetime.datetime.now(datetime.timezone.utc)
        dur = int(max(0, (time.time() - t0) * 1000))
        row["updated_at"] = end.isoformat()
        row["duration_ms"] = dur
        row["status"] = status_s
        row["response_summary"] = response_summary
        row["error_message"] = error_message
        _save("api_requests.json", api_requests)

    payload = {
        "workspace_id": workspace_id,
        "status": status,
        "sort": sort,
        "order": order,
        "limit": limit,
        "cursor": cursor,
    }

    if not isinstance(workspace_id, str) or not re.match(r"^lin_ws_[0-9A-Z]+$", workspace_id):
        _log_request("failed", payload, error_message="Invalid workspace_id format", workspace_for_log=None)
        return _err("VALIDATION_ERROR", "Invalid workspace_id format")
    if status is not None and (not isinstance(status, str) or status not in ["active", "archived"]):
        _log_request("failed", payload, error_message="Invalid status", workspace_for_log=workspace_id)
        return _err("VALIDATION_ERROR", "Invalid status")
    if sort is not None and sort not in ["created_at", "updated_at", "name", "key"]:
        _log_request("failed", payload, error_message="Invalid sort", workspace_for_log=workspace_id)
        return _err("VALIDATION_ERROR", "Invalid sort")
    if order is not None and order not in ["asc", "desc"]:
        _log_request("failed", payload, error_message="Invalid order", workspace_for_log=workspace_id)
        return _err("VALIDATION_ERROR", "Invalid order")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 100:
        _log_request("failed", payload, error_message="limit out of range", workspace_for_log=workspace_id)
        return _err("VALIDATION_ERROR", "limit out of range")

    workspaces = _load("workspaces.json")
    ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == workspace_id), None)
    if not ws:
        _log_request("failed", payload, error_message="Workspace not found", workspace_for_log=None)
        return _err("NOT_FOUND", "Workspace not found")
    if ws.get("status") != "active":
        _log_request("failed", payload, error_message="Workspace not active", workspace_for_log=workspace_id)
        return _err("UNAUTHORIZED", "Workspace not active")

    teams = _load("teams.json")
    scoped = [t for t in teams if isinstance(t, dict) and t.get("workspace_id") == workspace_id and t.get("status") in ("active", "archived")]
    if status is not None:
        scoped = [t for t in scoped if t.get("status") == status]

    sfield = sort or "name"
    sorder = order or "asc"
    reverse = (sorder == "desc")

    def _dt_field(row, field):
        v = row.get(field)
        if not isinstance(v, str):
            return None
        return _parse_dt(v)

    def _sort_key(row):
        if sfield in ("created_at", "updated_at"):
            dt = _dt_field(row, sfield)
            missing = 1 if dt is None else 0
            ts = dt.timestamp() if dt is not None else 0.0
            return (missing, ts, row.get("id") or "")
        if sfield == "name":
            return ((row.get("name") or "").lower(), row.get("id") or "")
        if sfield == "key":
            return ((row.get("key") or ""), (row.get("name") or "").lower(), row.get("id") or "")
        return ((row.get("name") or "").lower(), row.get("id") or "")

    scoped.sort(key=_sort_key, reverse=reverse)

    offset = 0
    if cursor is not None:
        if not isinstance(cursor, str) or cursor.strip() == "":
            _log_request("failed", payload, error_message="Invalid cursor", workspace_for_log=workspace_id)
            return _err("VALIDATION_ERROR", "Invalid cursor")
        try:
            pad = "=" * ((4 - len(cursor) % 4) % 4)
            raw = base64.urlsafe_b64decode((cursor + pad).encode("utf-8")).decode("utf-8")
            offset = int(raw)
            if offset < 0:
                raise ValueError()
        except Exception:
            _log_request("failed", payload, error_message="Invalid cursor", workspace_for_log=workspace_id)
            return _err("VALIDATION_ERROR", "Invalid cursor")

    total = len(scoped)
    page = scoped[offset:offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = None
    if has_more:
        next_cursor = base64.urlsafe_b64encode(str(next_offset).encode("utf-8")).decode("utf-8").rstrip("=")

    _log_request("succeeded", payload, response_summary={"returned": len(page), "total": total, "has_more": has_more}, workspace_for_log=workspace_id)
    return {
        "teams": page,
        "meta": {
            "total": total,
            "limit": limit,
            "has_more": has_more,
            "next_cursor": next_cursor
        }
    }

def list_projects(workspace_id, status=None, sort=None, order=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, re, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0148000" if __import__("os").path.isdir("./environment_mix/0148000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    api_requests = _load("api_requests.json")
    workspaces = _load("workspaces.json")
    projects = _load("projects.json")

    req_id = "lin_req_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f")
    req_row = {
        "id": req_id,
        "workspace_id": None,
        "tool_name": "list_projects",
        "status": "received",
        "request_payload": {
            "workspace_id": workspace_id,
            "status": status,
            "sort": sort,
            "order": order,
            "limit": limit,
            "cursor": cursor,
        },
        "response_summary": None,
        "error_message": None,
        "duration_ms": None,
        "created_at": now,
        "updated_at": now,
    }
    api_requests.append(req_row)
    _save("api_requests.json", api_requests)

    def _finish_ok(workspace_id_val, summary):
        api_requests2 = _load("api_requests.json")
        for r in reversed(api_requests2):
            if r.get("id") == req_id:
                r["workspace_id"] = workspace_id_val
                r["status"] = "succeeded"
                r["response_summary"] = summary
                r["error_message"] = None
                r["duration_ms"] = max(0, int((time.time() - t0) * 1000))
                r["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
                break
        _save("api_requests.json", api_requests2)

    def _finish_err(workspace_id_val, code, msg, **x):
        api_requests2 = _load("api_requests.json")
        for r in reversed(api_requests2):
            if r.get("id") == req_id:
                r["workspace_id"] = workspace_id_val
                r["status"] = "failed"
                r["response_summary"] = None
                r["error_message"] = msg
                r["duration_ms"] = max(0, int((time.time() - t0) * 1000))
                r["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
                break
        _save("api_requests.json", api_requests2)
        return _err(code, msg, **x)

    if not isinstance(workspace_id, str) or not re.match(r"^lin_ws_[0-9A-Z]+$", workspace_id):
        return _finish_err(None, "VALIDATION_ERROR", "Invalid workspace_id.")

    ws = next((w for w in workspaces if w.get("id") == workspace_id), None)
    if not ws:
        return _finish_err(None, "NOT_FOUND", "Workspace not found.")
    if ws.get("status") != "active":
        return _finish_err(workspace_id, "UNAUTHORIZED", "Workspace is not active.")

    allowed_status = {"planned", "started", "paused", "completed", "canceled", "archived"}
    if status is not None:
        if not isinstance(status, str) or status not in allowed_status:
            return _finish_err(workspace_id, "VALIDATION_ERROR", "Invalid status filter.")

    allowed_sort = {"created_at", "updated_at", "name", "start_date", "target_date"}
    if sort is None:
        sort = "updated_at"
    if not isinstance(sort, str) or sort not in allowed_sort:
        return _finish_err(workspace_id, "VALIDATION_ERROR", "Invalid sort field.")

    allowed_order = {"asc", "desc"}
    if order is None:
        order = "desc" if sort in {"updated_at", "created_at"} else "asc"
    if not isinstance(order, str) or order not in allowed_order:
        return _finish_err(workspace_id, "VALIDATION_ERROR", "Invalid order.")

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 100:
        return _finish_err(workspace_id, "VALIDATION_ERROR", "limit must be an integer between 1 and 100.")

    start = 0
    if cursor is not None:
        if not isinstance(cursor, str) or cursor.strip() == "":
            return _finish_err(workspace_id, "VALIDATION_ERROR", "Invalid cursor.")
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===").decode("utf-8")
            if not raw.startswith("off:"):
                return _finish_err(workspace_id, "VALIDATION_ERROR", "Invalid cursor.")
            start = int(raw.split(":", 1)[1])
            if start < 0:
                return _finish_err(workspace_id, "VALIDATION_ERROR", "Invalid cursor.")
        except Exception:
            return _finish_err(workspace_id, "VALIDATION_ERROR", "Invalid cursor.")

    rows = [p for p in projects if p.get("workspace_id") == workspace_id]
    if status is not None:
        rows = [p for p in rows if p.get("status") == status]

    def _sort_key(p):
        v = p.get(sort)
        if v is None:
            # Put nulls last for asc, first for desc (stable)
            return (1, "")
        return (0, v)

    rows.sort(key=_sort_key, reverse=(order == "desc"))

    total = len(rows)
    page = rows[start:start + limit]
    next_cursor = None
    has_more = start + limit < total
    if has_more:
        next_cursor = base64.urlsafe_b64encode(("off:%d" % (start + limit)).encode("utf-8")).decode("utf-8").rstrip("=")

    resp = {
        "projects": page,
        "total": total,
        "limit": limit,
        "has_more": has_more,
        "next_cursor": next_cursor,
        "sort": sort,
        "order": order,
    }
    _finish_ok(workspace_id, {"returned": len(page), "total": total, "has_more": has_more})
    return resp

def search_issues(workspace_id, query, team_id=None, project_id=None, status=None, priority=None, sort=None, order=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, re, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0148000" if __import__("os").path.isdir("./environment_mix/0148000") else "/app/database")
    def _load(n):
